import {Field} from 'alinea'

export type RangeField = Field.Create<
  number,
  {min?: number; max?: number; help?: string}
>

export function range(
  label: string,
  options: Field.Options<RangeField> = {}
): RangeField {
  return Field.create({
    label,
    options,
    // The module that renders the field, its default export is used
    view: '@/fields/Range.view'
  })
}

import {Field} from 'alinea/components'
import {
  useField,
  useFieldError,
  useFieldOptions
} from 'alinea/dashboard/hooks'
import {useId} from 'react'
import type {RangeField} from './Range'

interface RangeViewProps {
  field: RangeField
}

export default function RangeView({field}: RangeViewProps) {
  const [value, setValue] = useField(field)
  const options = useFieldOptions(field)
  const error = useFieldError(field)
  const id = useId()
  const {min = 0, max = 10} = options
  return (
    <Field
      htmlFor={id}
      label={options.label}
      description={options.help}
      error={error}
      required={options.required}
      readOnly={options.readOnly}
      shared={options.shared}
    >
      <input
        id={id}
        type="range"
        min={min}
        max={max}
        value={value ?? min}
        disabled={options.readOnly}
        onChange={event => setValue(Number(event.target.value))}
      />
    </Field>
  )
}

import {Config} from 'alinea'
